{"code": "# Let's try to use CoolProp to get the density of R-12 at 4°C and 1086 bar
try:
    from CoolProp.CoolProp import PropsSI
    # Temperature in K, Pressure in Pa
    T = 4 + 273.15  # 4°C in Kelvin
    P = 1086 * 1e5  # 1086 bar in Pa
    density = PropsSI('D', 'T', T, 'P', P, 'R12')
    print(f"Density at {T} K and {P/1e5} bar: {density} kg/m³")
except ImportError:
    print("CoolProp not available")
except Exception as e:
    print(f"Error: {e}")"}
